mapper.select:
SELECT p.id AS publisherId, p.name AS publisherName, p.code AS publisherCode, COALESCE(SUM(s.imp_count), 0) AS impCount, COALESCE(SUM(s.click_count), 0) AS clickCount, CASE WHEN COALESCE(SUM(s.imp_count), 0) = 0 THEN 0 ELSE ROUND(COALESCE(SUM(s.click_count), 0) * 100.0 / SUM(s.imp_count), 2) END AS clickRate, SUM(revenue) AS revenue, SUM(adx_revenue) as adxRevenue FROM publisher p LEFT JOIN ad_slot_stat s ON p.id = s.publisher_id
AND s.stat_date >= #{startDate}
AND s.stat_date <= #{endDate}
AND p.id = #{publisherId}
AND p.name LIKE CONCAT('%', #{publisherName}, '%')
GROUP BY p.id, p.name, p.code ORDER BY impCount DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(DISTINCT p.id)
FROM publisher p
LEFT JOIN ad_slot_stat s ON p.id = s.publisher_id

        AND s.stat_date >= #{startDate}


        AND s.stat_date <= #{endDate}



        AND p.id = #{publisherId}


        AND p.name LIKE CONCAT('%', #{publisherName}, '%')

SELECT sap.code AS adSlotId, sap.name AS adSlotName, st.id AS siteId, st.name AS siteName, p.id AS publisherId, p.name AS publisherName, COALESCE(SUM(s.imp_count), 0) AS impCount, COALESCE(SUM(s.click_count), 0) AS clickCount, CASE WHEN COALESCE(SUM(s.imp_count), 0) = 0 THEN 0 ELSE ROUND(COALESCE(SUM(s.click_count), 0) * 100.0 / SUM(s.imp_count), 2) END AS clickRate, SUM(revenue) AS revenue, SUM(adx_revenue) as adxRevenue FROM site_ad_placement sap LEFT JOIN site st ON sap.site_id = st.id LEFT JOIN publisher p ON st.publisher_id = p.id LEFT JOIN ad_slot_stat s ON sap.code = s.ad_slot_id
AND s.stat_date >= #{startDate}
AND s.stat_date <= #{endDate}
AND p.id = #{publisherId}
AND st.id = #{siteId}
GROUP BY sap.code, sap.name, st.id, st.name, p.id, p.name ORDER BY impCount DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(DISTINCT sap.code)
FROM site_ad_placement sap
LEFT JOIN site st ON sap.site_id = st.id
LEFT JOIN publisher p ON st.publisher_id = p.id
LEFT JOIN ad_slot_stat s ON sap.code = s.ad_slot_id

        AND s.stat_date >= #{startDate}


        AND s.stat_date <= #{endDate}



        AND p.id = #{publisherId}


        AND st.id = #{siteId}
